input.new_string:
# Custom exfiltration detection rule
# Detects HTTP POST requests to /telemetry/v2/report with exfil mode
# and suspicious body patterns (Base64 blob + hex signature)
alert http any any -> any any (
  msg:"Custom HTTP Exfiltration - Telemetry Blob with Signature";
  flow:to_server,established;
  content:"POST";
  http_method;
  content:"/telemetry/v2/report";
  http_uri;
  content:"X-TLM-Mode|3a|";
  http_header;
  content:"exfil";
  http_header;
  pcre:"/blob=[A-Za-z0-9+/]{80,}/";
  http_client_body;
  pcre:"/sig=[0-9a-fA-F]{64}/";
  http_client_body;
  sid:1000001;
  rev:1;
)

